import { describe, expect, it } from "vitest";
import {
  README_SENTINEL,
  README_STRUCTURE_VERSION,
  extractReadmeBody,
  getReadmePreview,
  getReadmeStructureVersion,
  migrateReadme,
  serializeReadme,
} from "./readme";

const LEGACY_SENTINEL =
  "# do not change, this is autogenerated and used by WerSu";

describe("serializeReadme", () => {
  it("emits the current structure version", () => {
    expect(README_SENTINEL).toContain(
      `wersu-readme-structure-version: ${README_STRUCTURE_VERSION}`,
    );
    expect(
      getReadmeStructureVersion(serializeReadme({ name: "My Book" })),
    ).toBe(README_STRUCTURE_VERSION);
  });

  it("emits the header, image, sentinel and body", () => {
    expect(
      serializeReadme(
        { name: "My Book", imageUrl: "https://example.com/cover.png" },
        "Some prose",
      ),
    ).toBe(
      [
        "# My Book",
        "",
        "![bookImage](https://example.com/cover.png)",
        "",
        README_SENTINEL,
        "",
        "Some prose",
      ].join("\n"),
    );
  });

  it("uses the description as the body when no body exists yet", () => {
    expect(
      serializeReadme({
        name: "My Book",
        description: "A short description",
        imageUrl: "https://example.com/cover.png",
      }),
    ).toBe(
      [
        "# My Book",
        "",
        "![bookImage](https://example.com/cover.png)",
        "",
        README_SENTINEL,
        "",
        "A short description",
      ].join("\n"),
    );
  });

  it("keeps an existing user body instead of overwriting it with the description", () => {
    expect(
      serializeReadme(
        {
          name: "My Book",
          description: "A short description",
        },
        "User-authored prose",
      ),
    ).toBe(
      [
        "# My Book",
        "",
        README_SENTINEL,
        "",
        "User-authored prose",
      ].join("\n"),
    );
  });

  it("omits the image, description and body when absent", () => {
    expect(serializeReadme({ name: "My Book" })).toBe(
      ["# My Book", "", README_SENTINEL].join("\n"),
    );
  });

  it("strips sentinels that are passed in as part of the body", () => {
    expect(
      serializeReadme(
        { name: "My Book" },
        `Some prose\n\n${README_SENTINEL}\n\n${LEGACY_SENTINEL}`,
      ),
    ).toBe(["# My Book", "", README_SENTINEL, "", "Some prose"].join("\n"));
  });
});

describe("extractReadmeBody", () => {
  it("returns everything below the current sentinel", () => {
    expect(
      extractReadmeBody(
        ["# My Book", "", README_SENTINEL, "", "Some prose"].join("\n"),
      ),
    ).toBe("Some prose");
  });

  it("supports the legacy sentinel", () => {
    expect(
      extractReadmeBody(
        ["# My Book", "", LEGACY_SENTINEL, "", "Some prose"].join("\n"),
      ),
    ).toBe("Some prose");
  });

  it("drops duplicated sentinels appended below the user content", () => {
    expect(
      extractReadmeBody(
        [
          "# My Book",
          "",
          LEGACY_SENTINEL,
          "",
          "Some prose",
          "",
          LEGACY_SENTINEL,
          "",
          LEGACY_SENTINEL,
        ].join("\n"),
      ),
    ).toBe("Some prose");
  });

  it("returns an empty body when there is no sentinel", () => {
    expect(extractReadmeBody("# My Book\n\nSome prose")).toBe("");
    expect(extractReadmeBody(undefined)).toBe("");
  });
});

describe("getReadmeStructureVersion", () => {
  it("reads the version marker", () => {
    expect(
      getReadmeStructureVersion(
        ["# My Book", "", README_SENTINEL].join("\n"),
      ),
    ).toBe(README_STRUCTURE_VERSION);
  });

  it("treats unversioned legacy READMEs as v1", () => {
    expect(
      getReadmeStructureVersion(
        ["# My Book", "", LEGACY_SENTINEL].join("\n"),
      ),
    ).toBe(1);
  });

  it("treats an unversioned caution-block README as v2", () => {
    const unversionedV2 = [
      "# My Book",
      "",
      "> [!CAUTION]",
      "> only change content below this info; the header is used by WerSu",
      "",
      "Some prose",
    ].join("\n");
    expect(getReadmeStructureVersion(unversionedV2)).toBe(2);
    expect(extractReadmeBody(unversionedV2)).toBe("Some prose");
  });

  it("returns 0 for unknown content", () => {
    expect(getReadmeStructureVersion(undefined)).toBe(0);
    expect(getReadmeStructureVersion("# My Book")).toBe(0);
  });
});

describe("migrateReadme", () => {
  it("upgrades a v1 README while preserving the user body", () => {
    const legacy = [
      "# Old Book",
      "![directoryImage](https://example.com/old.png)",
      "",
      "Old description",
      "",
      LEGACY_SENTINEL,
      "",
      "Some prose",
    ].join("\n");

    expect(
      migrateReadme(legacy, {
        name: "New Book",
        description: "New description",
        imageUrl: "https://example.com/new.png",
      }),
    ).toBe(
      [
        "# New Book",
        "",
        "![bookImage](https://example.com/new.png)",
        "",
        README_SENTINEL,
        "",
        "Some prose",
      ].join("\n"),
    );
  });

  it("seeds an empty migrated README with the description", () => {
    const legacy = [
      "# Old Book",
      "",
      LEGACY_SENTINEL,
    ].join("\n");

    expect(
      migrateReadme(legacy, {
        name: "Old Book",
        description: "Recovered description",
      }),
    ).toBe(
      [
        "# Old Book",
        "",
        README_SENTINEL,
        "",
        "Recovered description",
      ].join("\n"),
    );
  });

  it("also cleans duplicated legacy sentinels below the body", () => {
    const legacy = [
      "# Old Book",
      "",
      LEGACY_SENTINEL,
      "",
      "Some prose",
      "",
      LEGACY_SENTINEL,
      "",
      LEGACY_SENTINEL,
    ].join("\n");

    expect(migrateReadme(legacy, { name: "Old Book" })).toBe(
      ["# Old Book", "", README_SENTINEL, "", "Some prose"].join("\n"),
    );
  });
});

describe("getReadmePreview", () => {
  it("only shows the header above the sentinel", () => {
    expect(
      getReadmePreview(
        ["# My Book", "", README_SENTINEL, "", "Some prose"].join("\n"),
      ),
    ).toBe("# My Book");
  });
});
